import{_ as l,o as a,c as i,af as t}from"./chunks/framework.BmOFhHdK.js";const r="/assets/2022-05-25-10-21-15.CHHZ8e7U.png",m=JSON.parse('{"title":"路由 vs 代理 vs 网关","description":"","frontmatter":{},"headers":[],"relativePath":"blogs/2022/202205-router-proxy-gtw.md","filePath":"blogs/2022/202205-router-proxy-gtw.md","lastUpdated":1772904362000}'),o={name:"blogs/2022/202205-router-proxy-gtw.md"};function s(n,e,u,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="路由-vs-代理-vs-网关" tabindex="-1">路由 vs 代理 vs 网关 <a class="header-anchor" href="#路由-vs-代理-vs-网关" aria-label="Permalink to &quot;路由 vs 代理 vs 网关&quot;">​</a></h1><p>在阅读<a href="https://mp.weixin.qq.com/s/B0LVmFvI7kFtjFEM0FG_zw" target="_blank" rel="noreferrer">《为什么需要可编程代理》</a>的时候，发现在云原生网关的变迁史中，频繁的出现了“路由、代理、网关”。而我们日常所用的技术中心，也有不少的软硬件设备和这三个概念有关系，如路由器、代理服务器、API 网关等。让我产生了好奇，这三个概念有具体的联系吗？</p><p>在翻阅了部分资料后，大致做了一些总结。</p><h2 id="路由-——-move-packets-between-networks" tabindex="-1">路由 —— “move packets between networks” <a class="header-anchor" href="#路由-——-move-packets-between-networks" aria-label="Permalink to &quot;路由 —— “move packets between networks”&quot;">​</a></h2><ul><li>路由器 <ul><li>硬件路由 <ul><li>路由器工作在网络的 3 层；</li><li>对其通信两端来说都是透明的，内外网的主机不会查觉中间有路由器参与了操作；</li><li>路由器可以工作在低层，通过直接转化网络地址来转发数据包，它比代理服务器的速度要快；</li></ul></li><li>软（件）路由 <ul><li>结合软件的功能，通过拦截数据包来修改和转发到目标地址</li><li>(软路由更接近于代理服务器)</li></ul></li></ul></li></ul><h2 id="代理-——-「代为处理」" tabindex="-1">代理 —— 「代为处理」 <a class="header-anchor" href="#代理-——-「代为处理」" aria-label="Permalink to &quot;代理 —— 「代为处理」&quot;">​</a></h2><ul><li><p>代理服务器</p><ul><li>代理工作在 3 层以上，通常是 4 层和 7 层；</li><li>局域网中只有代理服务器能上网，只能依托代理服务器进行数据请求和接收，然后再转发； <ul><li>perform some useful service such as caching HTTP content, applying application-level filtering and authorization functions and so on</li></ul></li><li>不同的代理服务器提供不同的服务，通常提供WWW、FTP等常见服务；</li><li>代理通常连接的是两个或多个使用相同协议栈的端点(转发为主)；</li></ul></li><li><p>代理方式</p><ul><li>正向代理 代理外部地址 翻墙 <ul><li>NAT 通过解包，替换目标地址/端口</li></ul></li><li>反向代理 为内部多个机器提供统一的对外地址 <ul><li>负载均衡 对一组相同功能的机器进行的反向代理 <ul><li>(负载均衡是目的，反向代理是实现方式)</li></ul></li></ul></li></ul></li></ul><h2 id="网关-——-「网络关口」" tabindex="-1">网关 —— 「网络关口」 <a class="header-anchor" href="#网关-——-「网络关口」" aria-label="Permalink to &quot;网关 —— 「网络关口」&quot;">​</a></h2><ul><li>网关 <ul><li>网关是一个概念，不具体特指一类产品，只要连接两个不同的网络的设备都可以叫网关；</li><li>网关通常连接的是两个或多个使用不同协议的端点(协议转换)；</li><li>广义的网关：有进有出即为网关</li><li>狭义的网关 <ul><li>IP路由过程中的网关：子网的关口，所有对子网的访问需要先向网关(默认网关)寻址 <ul><li><a href="https://www.zhihu.com/question/21787311" target="_blank" rel="noreferrer">网关和路由器的区别是什么？</a></li></ul></li><li>API网关：对HTTP API进行拦截、监控、修改、转发</li></ul></li></ul></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p><img src="'+r+'" alt="Route vs Proxy vs Gateway"></p><blockquote><p>ps: 还顺便研究了一下 excalidraw 添加中文字体:</p><ul><li>Issue：<a href="https://github.com/excalidraw/excalidraw/issues/5245" target="_blank" rel="noreferrer">https://github.com/excalidraw/excalidraw/issues/5245</a></li><li>Spike：<a href="https://github.com/Anddd7/excalidraw/commit/97eca3fd347c9d3f3875996e7c49585307264e4e" target="_blank" rel="noreferrer">https://github.com/Anddd7/excalidraw/commit/97eca3fd347c9d3f3875996e7c49585307264e4e</a></li><li>Demo：<a href="https://excalidraw-anddd7.vercel.app/" target="_blank" rel="noreferrer">https://excalidraw-anddd7.vercel.app/</a></li></ul></blockquote>',12)])])}const f=l(o,[["render",s]]);export{m as __pageData,f as default};
